import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from native.engine import Engine  # noqa: E402
from native.geometry import Geometry  # noqa: E402


def _cube_frame(spin, dt, frames):
    """Cube Frame's picture after `frames` frames of `dt` ms, spin slider 1 at `spin`, the other two centred."""
    e = Engine(); e.set_geometry(Geometry("matrix", w=48, h=48))
    k = e.find("Cube Frame")
    assert k is not None, "no Cube Frame in the roster"
    e.select(k, dict(sx=0, ix=128, c1=spin, c2=128, c3=16))
    e.set_now(0)
    for _ in range(frames):
        e.frame(dt)
    return e.rgb().astype(int)


def test_a_rate_of_one_moves_at_short_frames():
    still = _cube_frame(128, 8, 3000)
    turning = _cube_frame(129, 8, 3000)                  # 3000 x 8 / 23 = about 1040 of 65536: six degrees
    assert np.abs(still - turning).sum() > 0, "a rate of 1 per frame left the cube standing at 8 ms frames"


def test_the_rate_does_not_depend_on_the_frame_length():
    # the same 24 s of clock at 8 ms and at 24 ms frames: the spin has to come out the same, give or take a step
    fine = _cube_frame(140, 8, 3000)
    coarse = _cube_frame(140, 24, 1000)
    diff = np.abs(fine - coarse).max(axis=2)
    assert (diff > 48).mean() < 0.02, f"{(diff > 48).mean():.1%} of the pixels differ between 8 ms and 24 ms frames"


